<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\ProductDraftContract as Contract;
require_once __DIR__.'/../../includes/Connector/Printify/CredentialReference.php';
require_once __DIR__.'/../../includes/Connector/Printify/ShopBinding.php';
if(!class_exists(\DigiForge\POD\PrintifyProductRequest::class))require_once __DIR__.'/../fixtures/printify-connector/stage34/CoreProductRequest.php';
require_once __DIR__.'/../../companion/digiforge-printify-connector/Preparation/ProductDraftContract.php';
final class PrintifyCompanionProductDraftTest extends TestCase {
 private function fixture():array{return (require __DIR__.'/../fixtures/printify-connector/stage34/product-fixture.php')();}
 public function testCreateIsPureAndReadbackStripsUnrelatedData():void{[$s,$i,$e,$r]=$this->fixture();$q=Contract::prepare('PRODUCT_CREATE',$s,$i,$e);self::assertSame('POST',$q['core_request']['method']);self::assertFalse($q['external_execution_authorized']);$r['customer_email']='private@example.invalid';$out=Contract::reconcile($q,$r);self::assertSame('PRODUCT_METADATA_OBSERVED_UNCERTIFIED',$out['state']);self::assertArrayNotHasKey('customer_email',$out);}
 public function testVisibleMetadataDoesNotVerifyPublication():void{[$s,$i,$e,$r]=$this->fixture();$r['visible']=true;$q=Contract::prepare('PRODUCT_CREATE',$s,$i,$e);$out=Contract::reconcile($q,$r);self::assertFalse($out['publication_verified']);self::assertSame('PRODUCT_METADATA_OBSERVED_UNCERTIFIED',$out['state']);}
 public function testShopStringIsCanonicalAndBooleanRejected():void{[$s,$i,$e,$r]=$this->fixture();$q=Contract::prepare('PRODUCT_CREATE',$s,$i,$e);$r['shop_id']='99002';self::assertFalse(Contract::reconcile($q,$r)['publication_verified']);$r['shop_id']=true;$this->expectException(InvalidArgumentException::class);Contract::reconcile($q,$r);}
 public function testUpdateHasFixedEndpointAndCompleteInventory():void{[$s,$i,$e,$r]=$this->fixture();$i+=['product_id'=>'fixture_product','known_variant_ids'=>[99005]];$e['product_version']=$e['expected_product_version']=2;$e['current_product_id']='fixture_product';$q=Contract::prepare('PRODUCT_UPDATE',$s,$i,$e);self::assertSame('/v1/shops/99002/products/fixture_product.json',$q['core_request']['endpoint']);self::assertArrayNotHasKey('blueprint_id',$q['core_request']['body']);self::assertArrayNotHasKey('print_provider_id',$q['core_request']['body']);self::assertSame('fixture_product',Contract::reconcile($q,$r)['product_id']);}
 public function testUpdateReadbackStillEnforcesImmutableIdentity():void{[$s,$i,$e,$r]=$this->fixture();$i+=['product_id'=>'fixture_product','known_variant_ids'=>[99005]];$e['product_version']=$e['expected_product_version']=2;$e['current_product_id']='fixture_product';$q=Contract::prepare('PRODUCT_UPDATE',$s,$i,$e);$r['blueprint_id']=42;$this->expectException(InvalidArgumentException::class);Contract::reconcile($q,$r);}
 public function testUpdateRejectsDifferentCurrentProduct():void{[$s,$i,$e]=$this->fixture();$i+=['product_id'=>'fixture_product','known_variant_ids'=>[99005]];$e['product_version']=$e['expected_product_version']=2;$e['current_product_id']='foreign';$this->expectException(InvalidArgumentException::class);Contract::prepare('PRODUCT_UPDATE',$s,$i,$e);}
 public function testUpdateRejectsIncompleteInventory():void{[$s,$i,$e]=$this->fixture();$i+=['product_id'=>'fixture_product','known_variant_ids'=>[99005,99006]];$e['product_version']=$e['expected_product_version']=2;$e['current_product_id']='fixture_product';$this->expectException(InvalidArgumentException::class);Contract::prepare('PRODUCT_UPDATE',$s,$i,$e);}
 public function testReadbackRejectsChangedEnvelope():void{[$s,$i,$e,$r]=$this->fixture();$q=Contract::prepare('PRODUCT_CREATE',$s,$i,$e);$q['evidence']['authorization_revision']=6;$this->expectException(InvalidArgumentException::class);Contract::reconcile($q,$r);}
 public function testUpdateReadbackRejectsDifferentProduct():void{[$s,$i,$e,$r]=$this->fixture();$i+=['product_id'=>'fixture_product','known_variant_ids'=>[99005]];$e['product_version']=$e['expected_product_version']=2;$e['current_product_id']='fixture_product';$q=Contract::prepare('PRODUCT_UPDATE',$s,$i,$e);$r['id']='foreign';$this->expectException(InvalidArgumentException::class);Contract::reconcile($q,$r);}
 /** @dataProvider invalidCases */
 public function testRejectsUnapprovedDraft(string $case):void{[$s,$i,$e]=$this->fixture();switch($case){case 'missing':unset($e['approval_receipt_sha256']);break;case 'hash':$e['catalog_receipt_sha256']='no';break;case 'revision':$e['authorization_revision']=6;break;case 'scope':$e['integration_id']=2;break;case 'foreign':$e['owned_uploads'][0]['provider_shop_id']='2';break;case 'duplicate':$i['variants'][]=$i['variants'][0];break;case 'unknown':$i['variants'][0]['id']=42;break;case 'free':$i['variants'][0]['price']=0;break;case 'float':$i['variants'][0]['price']=12.5;break;case 'html':$i['description']='<script>alert(1)</script>';break;case 'utf8':$i['title']="\xff";break;case 'outside':$i['print_areas'][0]['placeholders'][0]['images'][0]['x']=0;break;case 'angle':$i['print_areas'][0]['placeholders'][0]['images'][0]['angle']=90;break;case 'content':$e['owned_uploads'][0]['content_bounds']['x']=0;break;case 'version':$e['expected_product_version']=2;break;case 'missing-placement':$i['print_areas'][0]['variant_ids']=[];break;case 'foreign-image':$i['print_areas'][0]['placeholders'][0]['images'][0]['id']='foreign';break;case 'nan':$i['print_areas'][0]['placeholders'][0]['images'][0]['scale']=NAN;break;}$this->expectException(InvalidArgumentException::class);Contract::prepare('PRODUCT_CREATE',$s,$i,$e);}
 public static function invalidCases():array{return array_map(static fn($v)=>[$v],['missing','hash','revision','scope','foreign','duplicate','unknown','free','float','html','utf8','outside','angle','content','version','missing-placement','foreign-image','nan']);}
 /** @dataProvider readbackCases */
 public function testRejectsUnprovenReadback(string $case):void{[$s,$i,$e,$r]=$this->fixture();$q=Contract::prepare('PRODUCT_CREATE',$s,$i,$e);switch($case){case 'missing':unset($r['shop_id']);break;case 'foreign':$r['shop_id']='2';break;case 'published':$r['status']='published';break;case 'variant':$r['variants'][0]['id']=1;break;case 'http':$this->expectException(InvalidArgumentException::class);Contract::reconcile($q,$r,500);return;}$this->expectException(InvalidArgumentException::class);Contract::reconcile($q,$r);}
 public static function readbackCases():array{return [['missing'],['foreign'],['published'],['variant'],['http']];}
}
